query:
CREATE TABLE IF NOT EXISTS location_history (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  tracking_id UUID NOT NULL REFERENCES en_camino_tracking(id) ON DELETE CASCADE,
  reservation_id UUID NOT NULL,
  operation_type TEXT NOT NULL CHECK (operation_type IN ('entrega', 'devolucion')),
  latitude DOUBLE PRECISION NOT NULL,
  longitude DOUBLE PRECISION NOT NULL,
  accuracy DOUBLE PRECISION,
  recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_location_history_tracking ON location_history(tracking_id);
CREATE INDEX IF NOT EXISTS idx_location_history_reservation ON location_history(reservation_id, operation_type);
CREATE INDEX IF NOT EXISTS idx_location_history_recorded ON location_history(recorded_at);

